#!/usr/bin/env python3
"""Collect state from all devices in parallel."""
import json
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

VYOS_DEVICES = {
    "HQ-Edge": {"host": "192.168.122.11", "username": "vyos", "password": "test", "device_type": "vyos"},
    "Hub-A":   {"host": "192.168.122.12", "username": "vyos", "password": "test", "device_type": "vyos"},
    "Hub-B":   {"host": "192.168.122.13", "username": "vyos", "password": "test", "device_type": "vyos"},
    "ISP-A":   {"host": "192.168.122.14", "username": "vyos", "password": "test", "device_type": "vyos"},
    "ISP-B":   {"host": "192.168.122.15", "username": "vyos", "password": "test", "device_type": "vyos"},
}

MIKROTIK_DEVICES = {
    "Branch-1": {"host": "192.168.122.21", "username": "admin", "password": "test", "device_type": "mikrotik_routeros"},
    "Branch-2": {"host": "192.168.122.22", "username": "admin", "password": "test", "device_type": "mikrotik_routeros"},
    "Branch-3": {"host": "192.168.122.23", "username": "admin", "password": "test", "device_type": "mikrotik_routeros"},
    "Branch-4": {"host": "192.168.122.24", "username": "admin", "password": "test", "device_type": "mikrotik_routeros"},
}

LINUX_HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "username": "root", "password": "alpine", "device_type": "linux"},
    "B1-PC2": {"host": "192.168.122.32", "username": "root", "password": "alpine", "device_type": "linux"},
    "B2-PC1": {"host": "192.168.122.33", "username": "root", "password": "alpine", "device_type": "linux"},
    "B2-PC2": {"host": "192.168.122.34", "username": "root", "password": "alpine", "device_type": "linux"},
    "B3-PC1": {"host": "192.168.122.35", "username": "root", "password": "alpine", "device_type": "linux"},
    "B3-PC2": {"host": "192.168.122.36", "username": "root", "password": "alpine", "device_type": "linux"},
    "B4-PC1": {"host": "192.168.122.37", "username": "root", "password": "alpine", "device_type": "linux"},
    "B4-PC2": {"host": "192.168.122.38", "username": "root", "password": "alpine", "device_type": "linux"},
    "B4-PC3": {"host": "192.168.122.39", "username": "root", "password": "alpine", "device_type": "linux"},
    "B4-PC4": {"host": "192.168.122.40", "username": "root", "password": "alpine", "device_type": "linux"},
}

def collect_vyos(name, params):
    results = {}
    try:
        conn = ConnectHandler(**params)
        cmds = [
            "show interfaces",
            "show ip route",
            "show configuration commands",
            "show ip ospf neighbor",
            "show ip ospf interface",
        ]
        if name == "HQ-Edge":
            cmds += [
                "show ip bgp summary",
                "show ip bgp",
                "show ip bgp neighbors 203.0.113.1 received-routes",
                "show ip bgp neighbors 203.0.113.5 received-routes",
                "show ip bgp neighbors 203.0.113.1 advertised-routes",
                "show ip bgp neighbors 203.0.113.5 advertised-routes",
                "show nat source rules",
                "show nat source translations",
            ]
        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=30)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        try:
            results["vtysh_running"] = conn.send_command("vtysh -c 'show running-config'", read_timeout=30)
        except Exception as e:
            results["vtysh_running"] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["connection"] = f"ERROR: {e}"
    return name, results

def collect_mikrotik(name, params):
    results = {}
    try:
        conn = ConnectHandler(**params)
        cmds = [
            "/export terse",
            "/ip address print terse",
            "/ip route print terse",
            "/routing ospf neighbor print detail",
            "/routing ospf instance print detail",
            "/routing ospf area print detail",
            "/routing ospf interface-template print detail",
            "/ip firewall filter print terse",
            "/ip firewall nat print terse",
        ]
        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=30)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["connection"] = f"ERROR: {e}"
    return name, results

def collect_linux(name, params):
    results = {}
    try:
        conn = ConnectHandler(**params)
        cmds = [
            "ip addr show",
            "ip route show",
            "cat /etc/network/interfaces",
        ]
        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=15)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["connection"] = f"ERROR: {e}"
    return name, results

def main():
    all_results = {}
    with ThreadPoolExecutor(max_workers=19) as pool:
        futures = []
        for name, params in VYOS_DEVICES.items():
            futures.append(pool.submit(collect_vyos, name, params))
        for name, params in MIKROTIK_DEVICES.items():
            futures.append(pool.submit(collect_mikrotik, name, params))
        for name, params in LINUX_HOSTS.items():
            futures.append(pool.submit(collect_linux, name, params))
        for f in as_completed(futures):
            name, results = f.result()
            all_results[name] = results

    with open("state.json", "w") as fh:
        json.dump(all_results, fh, indent=2)

    for device in sorted(all_results.keys()):
        print(f"\n{'='*60}")
        print(f"  {device}")
        print(f"{'='*60}")
        for cmd, output in all_results[device].items():
            print(f"\n--- {cmd} ---")
            print(output)

if __name__ == "__main__":
    main()

